# -*- coding: utf-8 -*-
"""C0720 memor-: remember, record, commemorate; original lessons, no graphics."""
import json
from pathlib import Path
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
def K(w):return 'https://en.wiktionary.org/wiki/'+w
def S(w):return 'https://www.etymonline.com/word/'+w
def M(w):return 'https://www.merriam-webster.com/dictionary/'+w
def O(w):return 'https://www.oxfordlearnersdictionaries.com/definition/english/'+w
def A(h,w,m):return h+[[w,m]]
B=[['拉丁 memor','记着的；放在心上的']]
MEMORY=B+[['拉丁 memoria → 古法语 memoire／盎格鲁法语 memorie','记忆；记录'],['中古英语 memorie → 英语 memory','记忆力、回忆；后来也用于计算机存储信息的能力与装置']]
REMEMBER=B+[['拉丁 memorari → 晚期拉丁 re- + memorari → rememorari','放在心上 → 再想起'],['古法语 remembrer → 中古英语 remembren → 英语 remember','记住、想起；音变中插入 b']]
MEMORABLE=B+[['拉丁 memorare → memorabilis','使人想起 → 值得记住的'],['中古英语 memorable → 英语 memorable','令人难忘的']]
MEMORIAL=B+[['拉丁 memoria → memorialis；晚期拉丁名词 memoriale','记忆 → 与记忆有关的；纪念物'],['古法语 memorial 及拉丁语借入 → 中古英语／英语 memorial','纪念的；纪念物或纪念活动']]
MEMORIZE=A(MEMORY,'英语 memory 词干 + -ize → memorize','早期也指写下来留存；后来常说有意识地记牢')
MEMORANDUM=B+[['拉丁 memorare → memorandus 的中性单数 memorandum','使人记起 → 应当记住的事'],['拉丁 memorandum → 英语 memorandum','需要记下的事 → 备忘录、书面说明']]
COMMEMORATE=B+[['拉丁 memorare → commemorare，分词 commemoratus','使人想起；com- 在此常解释为加强'],['拉丁分词词干 → 英语 commemorate','通过活动、记录或物品使人记住']]
W=[
E('memory','/ˈmeməri/，也可读 /ˈmemri/','记忆力；记忆、回忆；内存','一件事已经过去，但它仍能留在脑中并再次被想起；既可以说这种能力，也可以说留下的某一段经历。','经法语 memoire、memorie 来自拉丁 memoria，后者由 memor“记着的”形成。计算机义是后来把保存信息的功能也比作记忆。',MEMORY,'a good memory 是记性好；a happy memory 是一段美好回忆，复数 memories 常指许多往事；from memory 是不看原文凭记忆。电脑的 memory 常说内存，需依技术语境理解。','have a good memory；childhood memories；from memory；in memory of；available memory。','memory 是能力或留下的内容；remember 是记住、想起这个动作或状态。memoir 是写成作品的回忆录，不是一段脑中的 memory。',('I have a vivid memory of our first day at that school.','我对我们到那所学校的第一天记忆鲜明。'),('She played the whole piece from memory.','她凭记忆演奏了整首曲子。'),('The application uses more memory when several large files are open.','同时打开几个大文件时，这个应用会占用更多内存。'),sources=[S('memory'),K('memory'),O('memory')]),
E('remember','英 /rɪˈmembə/；美 /rɪˈmembər/','记得；想起；记住去做；纪念','让某个人、某件事继续留在心里，或者把暂时没想到的事情重新带回脑中。','晚期拉丁 rememorari，由 re- 再 + memorari 记着形成，经古法语 remembrer 进入英语。中间的 b 是历史音变插入的，不是 re- 加 member“成员”。',REMEMBER,'remember doing 是记得曾经做过，镜头朝向过去；remember to do 是没有忘记去做，镜头朝向待办。remember someone 也能说长期怀念、记住那个人。','remember a name；remember doing；remember to do；be remembered for；remember someone as。','memorize 侧重主动学习以便记牢；remember 可以是自然记得或突然想起。remind someone 是使别人想起，不等于自己 remember。',('I remember meeting her at the station years ago.','我记得多年前在车站见过她。'),('Please remember to attach the file before sending the email.','发送邮件前请记得附上文件。'),('He is remembered for the kindness he showed to new students.','人们记得他对新生表现出的善意。'),sources=[S('remember'),K('remember'),O('remember')]),
E('remembered','英 /rɪˈmembəd/；美 /rɪˈmembərd/','记起了；记得；被铭记的；remember 的过去式、分词','某段记忆在过去浮现，或者某个人虽已离开，却仍被人放在心上；两种句型决定主动与被动。','remember + -ed，规则变化，词尾读 /d/；历史词根仍是 memor，不能把 remembered 拆成 member 的变化。',A(REMEMBER,'英语 remember → remembered','想起了、记住了；被记住'),'I remembered the address 是我想起了地址；be remembered as 是后来被人当作怎样的人记住。fondly remembered 常指被温暖地怀念，不是在说记忆力好。','remembered to do；fondly remembered；best remembered for；remembered as。','remembered to lock 表示没忘记锁并做了；remembered locking 表示回想起自己曾锁过。两者的过去时相同，后面的结构却改变意思。',('Halfway to the station, I remembered that I had left my ticket at home.','去车站的半路上，我想起自己把票落在家里了。'),('She is fondly remembered by generations of former students.','一代代曾经的学生都深情地怀念她。'),sources=[K('remembered'),S('remember'),O('remember')]),
E('remembering','/rɪˈmembərɪŋ/','记住、回想；remember 的现在分词或动名词','把“记得这件事”当作一个过程或任务来谈；有时也指回忆中的细节正在一点点回来。','remember + -ing，英语形式变化；没有另一个独立的古代 remembering 词根。',A(REMEMBER,'英语 remember + -ing → remembering','回想、记住的过程或任务'),'have trouble remembering names 是记名字有困难；worth remembering 是值得记住。remember 通常不必用进行时，但讲回忆逐渐浮现时可以说 I am remembering more。','trouble remembering；worth remembering；remembering the past；good at remembering。','remembering 是把内容记在脑中或调出来；memorizing 更突出刻意把内容学熟。记得一个人的脸，并不意味着专门背过。',('I have no trouble remembering faces, but names are harder.','我记人脸没什么困难，但名字更难记。'),('It is worth remembering that the first version was only a prototype.','值得记住的是，第一版当时只是一个原型。'),sources=[K('remembering'),S('remember'),O('remember')]),
E('memorize','/ˈmeməraɪz/','记牢；背熟','有意识地反复学习，直到不用看材料，也能把内容准确说出或做出。','memory 的词干 memor- + -ize，英语构词；早期也曾指写下来使之留存，后来常用义是记入脑中。英式还常拼 memorise。',MEMORIZE,'memorize a poem 是背诗；memorize lines 是背台词；memorize a route 是记熟路线。它说明要记牢，不自动表示机械死记，也不保证已经理解。','memorize a poem；memorize the lines；memorize a sequence；memorize key facts。','remember 是记得、想起；memorize 是为记牢而学习。understand 是理解，背得出一句话与理解它是两件可以同时做的事。',('The actors memorized their lines before the first rehearsal.','演员们在第一次排练前就背熟了台词。'),('I drew a simple map to help me memorize the route.','我画了一张简图，帮助自己记熟路线。'),sources=[S('memorize'),K('memorize'),M('memorize'),O('memorize')]),
E('memorization','英 /ˌmeməraɪˈzeɪʃən/；美 /ˌmemərəˈzeɪʃən/','记忆、背熟的过程','把陌生内容练到能记牢，这段学习过程作为一个整体来讨论；例如背台词需要多少时间、怎样配合理解。','memorize + -ation，英语动作名词；英式也常见 memorisation。不是把所有 memory“回忆”都换成这个较长的词。',A(MEMORIZE,'英语 memorize + -ation → memorization','有意识地记牢内容的过程'),'rote memorization 特指机械背记；单独 memorization 不一定否定理解，也可能与图像、例子和练习结合。通常作不可数名词。','rote memorization；aid memorization；memorization of vocabulary；memorization and understanding。','memory 是记忆能力或回忆，memorization 是把内容记牢的活动；a childhood memory 不能替换成 a childhood memorization。',('The lesson combines memorization with practical use of the new words.','这节课把新词的记忆与实际运用结合起来。'),('Understanding the pattern made memorization much easier.','理解规律后，记牢这些内容容易多了。'),sources=[K('memorization'),S('memorization'),O('memorization'),M('memorize')]),
E('memorable','/ˈmemərəbl/','令人难忘的；值得记住的','它足够鲜明、特别，事情过了很久仍能在脑中留下痕迹；不只是勉强能够背下来。','借拉丁 memorabilis，来自 memorare“使人想起、讲述”，再接 memor。现代可拿 memory 与 -able 帮助理解，但实际不是英语 memory 临时加 -able。',MEMORABLE,'a memorable evening 常是难忘的夜晚；a memorable line 是让人记得住的一句话。常带好评，但异常糟糕或奇特的经历也可能 memorable。','a memorable experience；a memorable performance；a memorable phrase；particularly memorable。','memorable 是事情容易留下印象；memorial 是为纪念而设的。a memorable speech 说演讲难忘，a memorial speech 说它用于纪念。',('The tiny café served us a surprisingly memorable meal.','那家小咖啡馆给我们做了一顿出乎意料地令人难忘的饭。'),('The film ends with a memorable image of an empty railway platform.','电影以一幅空荡站台的难忘画面收尾。'),sources=[S('memorable'),K('memorable'),O('memorable')]),
E('memorably','/ˈmemərəbli/','令人难忘地；以留下鲜明印象的方式','关注一句话怎样说、一幕戏怎样演，结果让人过后还记得那个表达或场面。','memorable + -ly，拼写从 -able 变为 -ably；英语副词，修饰表达、表演或某种特征。',A(MEMORABLE,'英语 memorable + -ly → memorably','以令人难忘的方式'),'memorably described 常引出一个很抓人的描述；memorably funny 说好笑得令人难忘。它不是“凭记忆地”，后者常说 from memory。','memorably described；memorably expressed；memorably funny；most memorably。','memorable 修饰事物：a memorable performance；memorably 修饰做法或特征：performed memorably。不要用它代替“记得很牢”。',('The speaker memorably compared the old system to a maze without exits.','演讲者把旧系统比作没有出口的迷宫，这个比喻令人难忘。'),('The final scene is brief but memorably tense.','最后一幕很短，但紧张得让人难忘。'),sources=[K('memorably'),O('memorably'),S('memorable')]),
E('memoir','英 /ˈmemwɑː/；美 /ˈmemwɑːr/','回忆录；回忆性记述','把自己亲历、记得的那段人生写出来，让读者从作者的眼睛重新经历它。','经法语 mémoire、较早的 memoire／memorie 接拉丁 memoria“记忆、记录”。它与 memory 同源，但经不同借入和词义发展成为作品名称，不是 memo + -ir。',B+[['拉丁 memoria → 法语 memoire／mémoire','记忆；保存下来的记述'],['法语借词 → 英语 memoir','书面记录 → 依个人经历写的回忆性作品']],'a memoir 可以侧重一段时期或一个主题；write one’s memoirs 常说撰写回忆录，复数未必表示很多本独立书。作者的个人视角是理解这个体裁的关键。','write a memoir；publish one’s memoirs；a memoir of childhood；a personal memoir。','autobiography 常给出本人较全面的生平叙述；memoir 常挑选特定经历来回望，二者在实际作品中也可能重叠。memo 是备忘便条。',('Her memoir focuses on the years she spent teaching in a small town.','她的回忆录重点写了在小镇教书的那些年。'),('He began writing his memoirs after finding a box of old letters.','发现一箱旧信后，他开始撰写回忆录。'),sources=[S('memoir'),K('memoir'),O('memoir')]),
E('memorandum','/ˌmeməˈrændəm/','备忘录；书面说明、通知','把需要记住、传达或留待查阅的事情写成文件，免得只靠口头和记性。','直接借拉丁 memorandum，是 memorandus“应当记住的”的中性单数，来自 memorare。字面上相当于“一件应当记住的事”，后来指记下它的文件。',MEMORANDUM,'工作中可指内部说明或正式记录；memorandum of understanding 常译谅解备忘录。普通复数 memorandums 与拉丁式 memoranda 都可见；简称 memo 更日常。','issue a memorandum；an internal memorandum；a memorandum on；memoranda。','memo 是它的缩略形式，语气通常更日常；memoir 是回忆录。文件叫 memorandum，并不只意味着给自己写的小提醒。',('The director circulated a memorandum explaining the new approval process.','主管发出了一份备忘录，说明新的审批流程。'),('The archive contains several memoranda about the proposed library.','档案馆保存了几份有关拟建图书馆的备忘录。'),sources=[S('memorandum'),K('memorandum'),O('memorandum')]),
E('memo','英 /ˈmeməʊ/；美 /ˈmemoʊ/','备忘录；简短通知、便条','把一件需要大家知道或自己记住的事，写成一份短小的文字消息。','memorandum 的截短形式；后半被省去后成为常用词，不是 memory 的任意缩写，也不是 memoir 的简称。',A(MEMORANDUM,'英语 memorandum 截短为 memo','较简短日常的备忘录、内部通知'),'send a memo to staff 是给员工发通知；a memo about the meeting 是有关会议的简短说明。口语 I did not get the memo 有时打趣自己没收到别人都知道的消息。','send a memo；an internal memo；a memo to staff；get the memo。','note 范围更宽，可只是几个字的笔记；memo 常带提醒、传达信息或内部工作通知的用途。memorandum 更正式完整。',('Please send a short memo to the team about the schedule change.','请给团队发一份简短通知，说明日程变化。'),('I left myself a memo with the three points I wanted to raise.','我给自己写了一张备忘便条，记下想提出的三点。'),sources=[S('memo'),K('memo'),O('memo')]),
E('memorial','/məˈmɔːriəl/','纪念物、纪念碑；纪念活动；纪念的','把“不要忘记这个人或这件事”放到外部世界里：一座碑、一场仪式、一项纪念安排，都能承担这个作用。','形容词来自拉丁 memorialis“与记忆有关的”；名词接晚期拉丁 memoriale。经古法语及拉丁借入英语，两支不能简单画成英语 memory 先加 -ial 再变名词。',MEMORIAL,'a memorial to someone 是纪念某人的物或场所；a memorial service 是追思仪式。它不必是一座大石碑，具体形式可以不同。','a memorial to；a war memorial；a memorial service；a memorial garden。','monument 常是较显著的纪念建筑或遗迹；memorial 更突出保留记忆的用途。memorable 则说令人难忘，不必是专门为纪念而设。',('The village built a small memorial to the rescue workers.','村里为救援人员建了一座小型纪念碑。'),('Friends gathered for a memorial service in the school hall.','朋友们聚在学校礼堂参加追思仪式。'),sources=[S('memorial'),K('memorial'),O('memorial_1'),O('memorial_2')]),
E('memorialize','/məˈmɔːriəlaɪz/','纪念；以作品、设施或活动使人长久记住','不只心里想念，还留下某种可被后来人看到、读到或参与的东西，让记忆延续。','英语 memorial + -ize，作动词；历史上也有递交书面陈情的用法，常用纪念义取 memorial“纪念物、纪念安排”这一面。英式也拼 memorialise。',A(MEMORIAL,'英语 memorial + -ize → memorialize','作纪念、使记忆留存；另有较旧陈情义'),'用一座花园、一篇文章或一部电影 memorialize 某人，都可能是在为其留下一份纪念；不局限于立碑。','memorialize someone in；memorialize an event；be memorialized by；a film memorializing。','remember 可以完全发生在内心；memorialize 常涉及外在表达或记录。commemorate 与它接近，常强调某次纪念行为。',('The new garden memorializes the volunteers who cared for the community.','新花园纪念了那些照顾社区的志愿者。'),('The film memorializes a way of life that has largely disappeared.','这部电影为一种已大多消失的生活方式留下了纪念。'),sources=[S('memorialize'),K('memorialize'),M('memorialize'),O('memorialize')]),
E('remembrance','/rɪˈmembrəns/','怀念；纪念；回想〔较正式〕','把过去的人与事重新放到心上，常带感情，或带一层郑重纪念的意味。','经古法语 remembrance，来自 remembrer“记得”，远接晚期拉丁 rememorari。现代可对应 remember + -ance，但法语已存在这个名词，英语名词并非只能从英语动词派生。',B+[['晚期拉丁 rememorari → 古法语 remembrer','再次记起、回想'],['古法语 remembrance → 中古英语 remembraunce → 英语 remembrance','回想、怀念、纪念']],'in remembrance of someone 是为了纪念某人；a day of remembrance 是纪念日。普通日常说“我记性好”用 memory，不说 good remembrance。','in remembrance of；a remembrance ceremony；a day of remembrance；fond remembrance。','memory 常说记忆能力或某一段回忆；remembrance 常强调怀念、纪念这一状态或行动，语气更庄重。',('They planted a tree in remembrance of their teacher.','他们种下一棵树来纪念老师。'),('The gathering was a quiet occasion for remembrance rather than speeches.','这次聚会让大家安静地追思，没有安排演讲。'),sources=[S('remembrance'),K('remembrance'),O('remembrance')]),
E('commemorate','/kəˈmeməreɪt/','纪念；使人记住某人或事件','用活动、物品或记录，把某件重要的事从“已经过去”变成“仍值得大家记住”。','来自拉丁 commemoratus，commemorare 的分词；com- 在此常解释为加强，memorare 是使人记起。不是一定要许多人“共同背诵”。',COMMEMORATE,'commemorate an anniversary 是纪念周年；一块牌匾也能 commemorate 某个事件。被纪念的事情可以喜庆，也可以悲痛，因此不等于 celebrate 的庆祝。','commemorate an event；commemorate the anniversary；a plaque commemorating；commemorate those who。','celebrate 常有庆祝、赞颂意味；commemorate 强调让记忆保留下来，可以是庄重悼念。记住一个密码通常不用这个词。',('The exhibition commemorates the opening of the city’s first public library.','这场展览纪念本市第一座公共图书馆的开放。'),('A plaque on the wall commemorates those who helped rebuild the village.','墙上的一块牌匾纪念了帮助重建村庄的人们。'),sources=[S('commemorate'),K('commemorate'),O('commemorate')]),
E('commemoration','/kəˌmeməˈreɪʃən/','纪念；纪念活动、仪式','把纪念这件事作为一个整体，或指组织起来的一场纪念活动；它不只是某个人脑中闪过的回忆。','来自古法语 commemoration、拉丁 commemoratio，接 commemorare 的分词词干。这条名词借入路线早于英语 commemorate，不能把它的历史简单画成现代动词加 -ion。',B+[['拉丁 memorare → commemorare → commemoratio','使人想起 → 提起、纪念的行动'],['古法语 commemoration → 中古英语 commemoracioun → 英语 commemoration','纪念；纪念仪式或活动']],'in commemoration of 表示为了纪念；hold a commemoration 把一次纪念活动当成可数事情。常见于新闻、历史与正式活动介绍。','in commemoration of；an annual commemoration；a commemoration ceremony。','commemorate 是动词，commemoration 是名词；celebration 常偏庆祝，commemoration 也可以郑重纪念不幸事件。',('The concert was held in commemoration of the orchestra’s founder.','这场音乐会是为纪念乐团创始人而举行的。'),('Local residents attended the annual commemoration at the harbour.','当地居民参加了港口举行的年度纪念活动。'),sources=[S('commemoration'),K('commemoration'),O('commemoration')]),
E('commemorative','/kəˈmemərətɪv/，美式也可读 /kəˈmeməreɪtɪv/','纪念性的；为纪念而制作或举办的','一枚币、一张邮票、一场展览被专门做出来，让人记住某个人、某一周年或某件事。','现代可拆 commemorate + -ive；也有接新拉丁 commemorativus 的来源分析，两条都回到拉丁 commemorare。不要把现代英语形式倒画成更早拉丁词的祖先。',B+[['拉丁 commemorare 及其形容词支线 commemorativus','使人记起；用于纪念的'],['新拉丁借入分析／英语 commemorate + -ive → commemorative','纪念性的；有时也指纪念邮票等物品']],'commemorative stamps 是纪念邮票；a commemorative edition 是纪念版。这个形容词说明制作目的，没保证它昂贵、稀少或有收藏收益。','a commemorative stamp；a commemorative coin；a commemorative edition；a commemorative ceremony。','memorable 是给人留下印象；commemorative 是特意用于纪念。纪念品不一定设计得令人难忘，两者不是一回事。',('The museum published a commemorative booklet for its fiftieth anniversary.','博物馆为五十周年出版了一本纪念小册子。'),('The envelope carried a commemorative stamp showing the old bridge.','信封上贴着一张印有老桥图案的纪念邮票。'),sources=[S('commemorative'),K('commemorative'),M('commemorative'),O('commemorative')]),
E('memorabilia','/ˌmemərəˈbɪliə/','纪念物；与人物、事件或活动有关的收藏品','一张旧门票、一件签名球衣、一张演出海报，因为与某段经历或某个人有联系，被特意保存下来。','借拉丁 memorabilia，是 memorabilis“值得记住的”的中性复数作名词；英语从值得记录的事、文字，后来发展到可收藏的实物。不是英语 memorable 再加一个任意词尾。',B+[['拉丁 memorare → memorabilis → 中性复数 memorabilia','使人想起 → 值得记住的 → 值得记下的事'],['拉丁 memorabilia → 英语 memorabilia','值得记录的事与文字 → 有关联和纪念意义的实物']],'sports memorabilia、film memorabilia 指体育或电影相关纪念收藏品。通常以复数整体使用；说一件可用 a piece of memorabilia，不说 a memorabilia。','sports memorabilia；a collection of memorabilia；a piece of memorabilia；collect memorabilia。','souvenir 常是旅行或活动时带回的纪念品；memorabilia 更突出与人物、历史、活动的关联及保存价值，不必是专门生产出售的商品。',('The display includes letters, photographs, and other theatre memorabilia.','展柜里有书信、照片和其他戏剧纪念物。'),('His most treasured piece of memorabilia is a ticket from his first concert.','他最珍爱的纪念物是第一次听音乐会留下的门票。'),sources=[S('memorabilia'),K('memorabilia'),O('memorabilia')]),
E('immemorial','/ˌɪməˈmɔːriəl/','远古的；久远得超出记忆所及的','往回追，已经找不到有人记得的起点：这件事似乎从很久很久以前就存在了。','法语 immémorial 接中世纪拉丁 immemorialis；否定 in- 在 m 前同化为 im-，加 memorialis“与记忆有关的”。这里不是“没有纪念碑”，而是古老到记忆追溯不到。',B+[['拉丁 memoria → memorialis → 中世纪拉丁否定 immemorialis','记忆相关 → 超出可记忆范围的'],['法语 immémorial → 英语 immemorial','久远得无法追忆其起点的']],'最常见于 from time immemorial 或 since time immemorial，表示自古以来。普通文章常是强调久远，不应仅凭这个短语认定一个精确年代。','from time immemorial；since time immemorial；an immemorial custom。','ancient 泛指古老；immemorial 更有“久到无人记得何时开始”的感觉。unmemorable 则是不值得记住、没留下印象，方向不同。',('People have told stories around fires from time immemorial.','自古以来，人们就在火堆旁讲故事。'),('The villagers spoke of the festival as an immemorial tradition.','村民们把这个节日称为极其久远的传统。'),sources=[S('immemorial'),K('immemorial'),O('immemorial')]),
]
ROOT=dict(id='C0720',meaning='记着；放在心上；使人记起',core='事情过去了，仍能在心里留下痕迹；也可以写下来、办活动、留下实物，帮助以后的人记住。',image='memory 是脑中的记忆；memo 是纸上待记的事；memoir 是写出来的经历；memorial 是让记忆留在公共世界的纪念物。',intro='拉丁 memor 表示记着的、心中有数的，由此形成 memoria“记忆”和 memorare“使人想起”。英语借入多条拉丁、法语支线，也继续构词。remember 的 b 来自历史音变，它与 member“成员”没有这里所需的词源关系。',forms='memor- 在 memory、memorize、memorial 等词中明显；经法语音变的 remember、remembrance 写成 membr-。memo 是 memorandum 的缩略，memoir 是法语借词，两者虽然很像，使用场景不同。',branches=[['记忆与想起来','memory, remember, remembered, remembering'],['有意识地学到记牢','memorize, memorization'],['让人留下印象','memorable, memorably'],['把记忆或待办写下来','memoir, memorandum, memo'],['纪念物与怀念','memorial, memorialize, remembrance'],['让重要的人与事不被忘记','commemorate, commemoration, commemorative'],['与往事相连的物品','memorabilia'],['记忆已经追不到的久远','immemorial']],contrasts='remember 是记得，memorize 是有意识地记牢；memorable 是令人难忘，memorial 与 commemorative 是为纪念而设。memo 是备忘录，memoir 是回忆录，memory 可以只是脑中的一段回忆。',practice='You remember a trip, write a memoir about it, and keep a ticket as memorabilia. At work, a memo records what must not be forgotten. 用旅行和工作两个场景，把看起来相似的几个词分开。',words=[],exclude={})
