 m=json.loads((BASE/'.cache/batch200/rewrite_vid.json').read_text());r=next(x for x in m['roots'] if x['id']==ROOT['id']);ROOT['words']=[w for w in r['family'] if '-' not in w]
 assert set(ROOT['words'])&set(m['owned_words'])=={e['word'] for e in W},(set(ROOT['words'])&set(m['owned_words'])-{e['word'] for e in W},{e['word'] for e in W}-set(ROOT['words']))
 assert len(W)==len({e['word'] for e in W}) and all(len(e['examples'])>=2 and len(e['history'])>=2 for e in W)
 OUT.mkdir(parents=True,exist_ok=True)
 (OUT/'roots_batch200_vid_46.json').write_text(json.dumps([ROOT],ensure_ascii=False,indent=2));(OUT/'words_batch200_vid_46.json').write_text(json.dumps(W,ensure_ascii=False,indent=2))
 print('memor:',len(W),'words;',sum(len(e['examples']) for e in W),'examples;',len(ROOT['words']),'references')
